package com.tencent.weknora.knowledge;

import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.sun.net.httpserver.HttpServer;
import com.tencent.weknora.model.client.CallContext;
import com.tencent.weknora.task.*;
import java.net.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.config.AutowireCapableBeanFactory;

/** Explicit live Neo4j/APOC acceptance: real shared upload -> worker -> graph -> public reads. */
@org.springframework.boot.test.context.SpringBootTest(properties={"weknora.jwt-secret=isolated-native-pipeline-trace-secret","weknora.bridge.enabled=false","weknora.knowledge.processing.enabled=true","weknora.knowledge.upload.enabled=true","weknora.tasks.enabled=true","weknora.tasks.poll-millis=3600000","weknora.retrieve-driver=sqlite","SSRF_WHITELIST=127.0.0.1","SSRF_DNS_WHITELIST_ONLY=true","logging.level.root=WARN","debug=false","NEO4J_ENABLE=true","NEO4J_USERNAME=neo4j","NEO4J_PASSWORD=isolated-test"})
@org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
class GraphExtractionPipelineHttpIntegrationIT {
  @org.springframework.test.context.DynamicPropertySource static void properties(org.springframework.test.context.DynamicPropertyRegistry p){KnowledgeProcessingSpanPipelineHttpIntegrationTest.properties(p);p.add("NEO4J_URI",()->Objects.requireNonNull(System.getProperty("weknora.graph.test.uri"),"isolated actual Neo4j URI required"));}
  @Autowired AutowireCapableBeanFactory beans;@Autowired GraphExtractionHandler handler;@Autowired Neo4jGraphRepository graph;@Autowired QuestionGenerationHandler question;@Autowired SummaryGenerationHandler summary;
  final KnowledgeProcessingSpanPipelineHttpIntegrationTest f=new KnowledgeProcessingSpanPipelineHttpIntegrationTest();final ObjectMapper json=new ObjectMapper();final AtomicInteger graphChats=new AtomicInteger();HttpServer server;Runnable during=()->{};
  @BeforeEach void setup()throws Exception{beans.autowireBean(f);f.setup();f.jdbc.update("UPDATE knowledge_bases SET indexing_strategy=?,extract_config=?,chunking_config=?,question_generation_config='{}',auto_tag_config='{}' WHERE id='trace-kb'",json.writeValueAsBytes(json.createObjectNode().put("vector_enabled",true).put("keyword_enabled",true).put("graph_enabled",true)),json.writeValueAsBytes(json.createObjectNode().put("enabled",true).set("tags",json.createArrayNode().add("owns"))),json.writeValueAsBytes(json.createObjectNode().put("chunk_size",1024).put("chunk_overlap",0)));
    server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/v1/",exchange->{try{JsonNode body=json.readTree(exchange.getRequestBody());ObjectNode response;if(exchange.getRequestURI().getPath().endsWith("chat/completions")){boolean isGraph=body.path("max_tokens").asInt()==8192;String reply;if(isGraph){graphChats.incrementAndGet();during.run();reply="[{\"entity\":\"Alice\",\"entity_attributes\":[\"Owner\"]},{\"entity\":\"Release\"},{\"entity1\":\"Alice\",\"entity2\":\"Release\",\"relation\":\"owns\"}]";}else if(body.path("messages").get(0).path("role").asText().equals("system"))reply="{\"summary\":\"Objective native release summary.\",\"gist\":\"Release headline\",\"topics\":[\"Delivery\"]}";else reply="Who owns release access?\nWhich release policy applies?\nWhere are release checkpoints?";response=json.createObjectNode().set("choices",json.createArrayNode().add(json.createObjectNode().put("finish_reason","stop").set("message",json.createObjectNode().put("role","assistant").put("content",reply))));}else{var data=json.createArrayNode();for(int i=0;i<body.path("input").size();i++)data.add(json.createObjectNode().put("index",i).set("embedding",json.createArrayNode().add(1).add(0).add(0)));response=json.createObjectNode().set("data",data);}byte[] bytes=json.writeValueAsBytes(response);exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(200,bytes.length);try(var out=exchange.getResponseBody()){out.write(bytes);}}finally{exchange.close();}});server.start();var p=json.createObjectNode().put("provider","generic").put("base_url","http://127.0.0.1:"+server.getAddress().getPort()+"/v1");p.set("embedding_parameters",json.createObjectNode().put("dimension",3));f.jdbc.update("UPDATE models SET parameters=? WHERE id='trace-embedding'",p.toString());f.jdbc.update("INSERT INTO models(id,tenant_id,name,type,source,parameters,is_builtin,status) VALUES('trace-graph-model',8,'unknown','KnowledgeQA','remote',?,false,'active') ON CONFLICT(id) DO UPDATE SET parameters=excluded.parameters",p.toString());f.jdbc.update("UPDATE knowledge_bases SET summary_model_id='trace-graph-model' WHERE id='trace-kb'");}
  @AfterEach void cleanup(){if(server!=null)server.stop(0);for(String id:f.jdbc.queryForList("SELECT id FROM knowledges WHERE tenant_id=8 AND knowledge_base_id='trace-kb'",String.class))try(var call=CallContext.timeout(Duration.ofSeconds(10))){graph.delete("trace-kb",id,call,()->{});}f.jdbc.update("UPDATE knowledge_bases SET extract_config='{}',question_generation_config='{}',auto_tag_config='{}',summary_model_id='' WHERE id='trace-kb'");}
  String prepared(boolean enhancements)throws Exception{String id=f.upload("Alice owns release access and delivery policy. "+UUID.randomUUID());if(enhancements){f.jdbc.update("UPDATE knowledge_bases SET question_generation_config=? WHERE id='trace-kb'","{\"enabled\":true,\"question_count\":3}".getBytes(java.nio.charset.StandardCharsets.UTF_8));f.jdbc.update("UPDATE knowledges SET metadata=? WHERE id=?","{\"process_overrides\":{\"summary_enabled\":true}}",id);}var doc=f.claim("default");assertTrue(f.document.execute(doc,f.cancellation(doc)).path("indexed").asBoolean());f.tasks.complete(doc,json.createObjectNode());var post=f.claim("postprocess");var output=f.postprocess.execute(post,f.cancellation(post));assertEquals(1,output.path("enqueued_graph_count").asInt());f.tasks.complete(post,json.createObjectNode());return id;}
  int pending(String id){return f.jdbc.queryForObject("SELECT pending_subtasks_count FROM knowledges WHERE id=?",Integer.class,id);}
  void noGraph(String id){assertEquals(0,graph.counts("trace-kb",id).path("Entities").asInt());assertEquals(0,graph.counts("trace-kb",id).path("Relations").asInt());}
  JsonNode row(JsonNode rows,String kind){for(var row:rows)if(row.path("kind").asText().equals(kind))return row;throw new AssertionError("missing index "+kind);}
  @Test void sharedNativeUploadPublishesActualGraphAndPublicOwnerEvidence()throws Exception{String id=prepared(false);assertEquals(1,pending(id));var job=f.claim("graph");assertEquals(8,job.tenantId());assertEquals(4,job.maxAttempts());assertEquals(1800000,job.timeoutMillis());assertEquals(2,handler.execute(job,f.cancellation(job)).path("nodes_added").asInt());f.tasks.complete(job,json.createObjectNode());assertEquals(0,pending(id));assertEquals("completed",f.jdbc.queryForObject("SELECT parse_status FROM knowledges WHERE id=?",String.class,id));var counts=row(f.get(id,"index-status",f.callerToken,200).path("indexes"),"graph");assertEquals(2,counts.path("count").asInt());assertEquals(1,counts.path("relation_count").asInt());assertEquals("completed",counts.path("status").asText(),counts.toString());String chunk=job.payload().path("chunk_id").asText();var details=row(f.get(id,"chunks/"+chunk+"/details",f.callerToken,200).path("indexes"),"graph");assertTrue(details.path("available").asBoolean());assertEquals(2,details.path("graph").path("nodes").size());assertEquals(1,details.path("graph").path("relations").size());for(var node:details.path("graph").path("nodes")){assertFalse(node.path("id").asText().isEmpty());assertEquals(chunk,node.path("chunk_ids").get(0).asText());}f.get(id,"chunks/"+chunk+"/details",f.foreignToken,403);f.get(id,"index-status",f.foreignToken,403);f.assertNativeTrace(id,"done");assertEquals("done",f.node(f.get(id,"spans",f.callerToken,200).path("trace"),"postprocess.graph.chunk[0]").path("status").asText());}
  @Test void graphQuestionsAndSummaryDrainOnlyTheirOwnSharedSlots()throws Exception{String id=prepared(true);assertEquals(3,pending(id));var g=f.claim("graph");handler.execute(g,f.cancellation(g));f.tasks.complete(g,json.createObjectNode());assertEquals(2,pending(id));var q=f.claim("question");question.execute(q,f.cancellation(q));f.tasks.complete(q,json.createObjectNode());assertEquals(1,pending(id));var s=f.claim("summary");summary.execute(s,f.cancellation(s));f.tasks.complete(s,json.createObjectNode());assertEquals(0,pending(id));assertEquals("completed",f.jdbc.queryForObject("SELECT parse_status FROM knowledges WHERE id=?",String.class,id));assertEquals(2,graph.counts("trace-kb",id).path("Entities").asInt());assertEquals(3,json.readTree(f.jdbc.queryForObject("SELECT metadata FROM chunks WHERE id=?",String.class,g.payload().path("chunk_id").asText())).path("generated_questions").size());assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM chunks WHERE knowledge_id=? AND chunk_type='summary'",Integer.class,id));}
  @Test void revisionChangedDuringChatDoesNotPublishOldGraph()throws Exception{String id=prepared(false);var job=f.claim("graph");during=()->f.jdbc.update("UPDATE chunks SET content_revision=1 WHERE id=?",job.payload().path("chunk_id").asText());assertEquals("chunk_changed",handler.execute(job,f.cancellation(job)).path("skipped").asText());noGraph(id);assertEquals(0,pending(id));}
  @Test void supersededChatDoesNotWriteGraphOrDrainSuccessorCounter()throws Exception{String id=prepared(false);var job=f.claim("graph");during=()->{f.tracker.open(8,id,"successor");f.jdbc.update("UPDATE knowledges SET pending_subtasks_count=3 WHERE id=?",id);};assertEquals("attempt_superseded",handler.execute(job,f.cancellation(job)).path("skipped").asText());noGraph(id);assertEquals(3,pending(id));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM java_graph_task_drains WHERE task_id=?",Integer.class,job.id()));}
  @Test void lostLeaseDuringChatCannotPublishOrDrain()throws Exception{String id=prepared(false);var job=f.claim("graph");during=()->f.jdbc.update("UPDATE java_task_jobs SET lease_owner='successor' WHERE id=?",job.id());assertThrows(CancellationException.class,()->handler.execute(job,f.cancellation(job)));noGraph(id);assertEquals(1,pending(id));}
  @Test void businessCancelDuringChatSkipsPublishAndDrainsItsOwnSlot()throws Exception{String id=prepared(false);var job=f.claim("graph");during=()->f.jdbc.update("UPDATE knowledges SET parse_status='cancelled' WHERE id=?",id);assertEquals("knowledge_cancelled",handler.execute(job,f.cancellation(job)).path("skipped").asText());noGraph(id);assertEquals(0,pending(id));assertEquals("cancelled",f.jdbc.queryForObject("SELECT parse_status FROM knowledges WHERE id=?",String.class,id));}
  @Test void realHttpCancelDuringChatRetainsTextIndexesAndPreventsGraph()throws Exception{String id=prepared(false);var job=f.claim("graph");long indexes=f.count("lite_embeddings",id);during=()->{try{var response=f.mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/knowledge/"+id+"/cancel-parse").header("Authorization","Bearer "+f.callerToken)).andReturn().getResponse();assertEquals(200,response.getStatus());}catch(Exception e){throw new RuntimeException(e);}};assertThrows(CancellationException.class,()->handler.execute(job,f.cancellation(job)));noGraph(id);assertEquals(0,pending(id));assertEquals(indexes,f.count("lite_embeddings",id));}
  @Test void actualGraphTransactionRollsBackNodesWhenGuardFailsBeforeRelations()throws Exception{String id=prepared(false);var checks=new AtomicInteger();try(var call=CallContext.timeout(Duration.ofSeconds(10))){assertThrows(CancellationException.class,()->graph.add("trace-kb",id,new GraphExtractionText.Graph(List.of(new GraphExtractionText.Node("Atomic",List.of("first"),List.of("source"))),List.of(new GraphExtractionText.Relation("Atomic","Target","owns"))),call,()->{if(checks.incrementAndGet()==3)throw new CancellationException("lease lost after node insertion");}));}assertEquals(3,checks.get());noGraph(id);assertEquals(1,pending(id));}
  @Test void initialDocumentReplacementRemovesOwnedHistoricalGraphBeforeEmbedding()throws Exception{String id=f.upload("Current release policy "+UUID.randomUUID());try(var call=CallContext.timeout(Duration.ofSeconds(10))){graph.add("trace-kb",id,new GraphExtractionText.Graph(List.of(new GraphExtractionText.Node("Historical",List.of("old"),List.of("old-chunk"))),List.of()),call,()->{});}assertEquals(1,graph.counts("trace-kb",id).path("Entities").asInt());var doc=f.claim("default");assertTrue(f.document.execute(doc,f.cancellation(doc)).path("indexed").asBoolean());f.tasks.complete(doc,json.createObjectNode());assertEquals(0,graph.counts("trace-kb",id).path("Entities").asInt());var post=f.claim("postprocess");f.postprocess.execute(post,f.cancellation(post));f.tasks.complete(post,json.createObjectNode());var g=f.claim("graph");handler.execute(g,f.cancellation(g));f.tasks.complete(g,json.createObjectNode());assertEquals(2,graph.counts("trace-kb",id).path("Entities").asInt());assertTrue(graph.detail("trace-kb",id,"old-chunk").path("nodes").isEmpty());}
  @Test void actualGraphDeletionRollsBackWhenOwnerLeaseGuardFailsAfterDeletingNodes()throws Exception{String id=f.upload("Rollback cleanup "+UUID.randomUUID());try(var call=CallContext.timeout(Duration.ofSeconds(10))){graph.add("trace-kb",id,new GraphExtractionText.Graph(List.of(new GraphExtractionText.Node("Historical",List.of("old"),List.of("old-chunk"))),List.of()),call,()->{});}var checks=new AtomicInteger();try(var call=CallContext.timeout(Duration.ofSeconds(10))){assertThrows(CancellationException.class,()->graph.delete("trace-kb",id,call,()->{if(checks.incrementAndGet()==3)throw new CancellationException("lost lease after delete");}));}assertEquals(3,checks.get());assertEquals(1,graph.counts("trace-kb",id).path("Entities").asInt());}

}
